// Do-it-yourself and Debug challenges, keyed by the lesson heading.
// kind 'diy': the student writes code from a task. kind 'debug': the editor opens with broken code to fix.
// expect: exact program output. goals: extra checks on the code (re = must match, no = must not match).
const diy = (task, expect, solution, hint, goals = [], why = '') => ({ kind: 'diy', task, expect, solution, hint, goals, why });
const debug = (task, code, expect, solution, hint, goals = [], why = '') => ({ kind: 'debug', task, code, expect, solution, hint, goals, why });

const fdiy = (task, expect, solution, hint, goals, why, start) => ({ ...diy(task, expect, solution, hint, goals, why), full: true, start });
const fdebug = (task, code, expect, solution, hint, goals, why) => ({ ...debug(task, code, expect, solution, hint, goals, why), full: true });

