      'class A {\nprotected:\n  int secret;\npublic:\n  A() {\n    secret = 1;\n  }\n};\n\nclass B : public A {\npublic:\n  int peek() {\n    return secret;\n  }\n};\n\nint main() {\n  B b;\n  cout << b.peek() << endl;\n  return 0;\n}',
